Definition add_factors_entail_wit_1 := 
(
forall (nprime_pre: Z) (primes_pre: Z) (v_pre: Z) (pre: (@list Z)) (k0: Z) (v0: Z) (all_2: (@list Z)) (PreH1 : ((Zlength (all_2)) = 256)) (PreH2 : ((sublist (0) (k0) (all_2)) = pre)) (PreH3 : (v_pre = v0)) (PreH4 : (1 <= v0)) (PreH5 : (v0 <= 1000000001)) (PreH6 : (0 <= k0)) (PreH7 : (k0 <= 200)) (PreH8 : ((Zlength (pre)) = k0)) ,
  (Int64Array.full primes_pre 256 all_2 )
  **  ((nprime_pre) # Int  |-> k0)
|--
  EX (all: (@list Z))  (fs: (@list Z)) ,
  “ (1 <= v0) ” 
  &&  “ (v0 <= 1000000001) ” 
  &&  “ (1 <= v_pre) ” 
  &&  “ (v_pre <= v0) ” 
  &&  “ (2 <= 2) ” 
  &&  “ (2 <= 31624) ” 
  &&  “ (0 <= k0) ” 
  &&  “ (k0 <= 200) ” 
  &&  “ ((Zlength (pre)) = k0) ” 
  &&  “ (0 <= (Zlength (fs))) ” 
  &&  “ ((Zlength (fs)) <= 29) ” 
  &&  “ ((Zlength (all)) = 256) ” 
